/*
 * A043420  Numbers whose base-7 representation contains exactly four 6's.
 * https://oeis.org/A043420
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 98, u32 n <= 2500, u64 n <= 2500,
 *            u128 n <= 2500, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Note: This sequence is not given by a simple closed formula but
 * can be generated by combinatorial enumeration.  The algorithm
 * determines the length of the base‑7 representation that contains
 * exactly four 6's, then builds the number digit by digit in
 * numeric order.
 */
#include <stdint.h>
#include <stddef.h>

/* Precomputed binomial coefficients C[n][k] for 0 ≤ n ≤ 20 */
static unsigned long long binom[21][21];
/* Precomputed powers 6^k for 0 ≤ k ≤ 20 */
static unsigned long long pow6[21];
static int initialized = 0;

/* Initialise tables once */
static void init_tables(void) {
    if (initialized)
        return;
    for (int n = 0; n <= 20; ++n) {
        binom[n][0] = binom[n][n] = 1;
        for (int k = 1; k < n; ++k) {
            binom[n][k] = binom[n - 1][k - 1] + binom[n - 1][k];
        }
    }
    pow6[0] = 1;
    for (int i = 1; i <= 20; ++i) {
        pow6[i] = pow6[i - 1] * 6ULL;
    }
    initialized = 1;
}

/* Number of valid length‑len numbers (exactly four 6's, no leading zero) */
static unsigned long long count_len_valid(int len) {
    if (len < 4)
        return 0ULL;
    unsigned long long total = binom[len][4] * pow6[len - 4];
    unsigned long long zero_msd = 0ULL;
    if (len >= 5)
        zero_msd = binom[len - 1][4] * pow6[len - 5];
    return total - zero_msd;
}

/* Return the n-th term (n ≥ 1) of sequence A043420. */
seq_t a(idx_t n) {
    init_tables();

    /* Find the length of the base-7 representation. */
    unsigned long long left = (unsigned long long)n;
    int len = 4;
    while (1) {
        unsigned long long cnt = count_len_valid(len);
        if (left > cnt) {
            left -= cnt;
            ++len;
        } else {
            break;
        }
    }

    /* Construct the number digit by digit. */
    seq_t val = 0;
    int rem6 = 4;          /* remaining digits that must be 6 */
    int remPos = len;      /* remaining positions to fill */

    for (int pos = 0; pos < len; ++pos) {
        int start = (pos == 0) ? 1 : 0;  /* no leading zero */
        for (int d = start; d <= 6; ++d) {
            int new_rem6 = rem6;
            if (d == 6)
                --new_rem6;

            if (new_rem6 < 0 || new_rem6 > remPos - 1) {
                continue; /* impossible combination */
            }

            unsigned long long cnt = binom[remPos - 1][new_rem6]
                                     * pow6[remPos - 1 - new_rem6];

            if (left > cnt) {
                left -= cnt;
            } else {
                /* choose this digit */
                val = val * 7 + (seq_t)d;
                rem6 = new_rem6;
                --remPos;
                break;
            }
        }
    }

    return val;
}
